xf:group.script:
				/**
				 * //property handling
				 * $w.log("id:" + options.id);
				 * $w.log("style:" + options.style);
				 * $w.log("class:" + options.class);
				 * $w.log("ref:" + options.ref);
				 * $w.log("readOnly:" + options.readOnly);
				 * $w.log("dComboDataList:" + options.dComboDataList);
				 * $w.log("dComboLabel:" + options.dComboLabel);
				 * $w.log("dComboValue:" + options.dComboValue);
				 * $w.log("nextTabID:" + options.nextTabID);
				 *
				 * //event trigger
				 * udc_obj.trigger("onTelChange", [param1]); 
				*/

				/**
				 * //property handling
				 * $w.log("id:" + options.id);
				 * $w.log("style:" + options.style);
				 * $w.log("class:" + options.class);
				 * $w.log("ref:" + options.ref);
				 * $w.log("readOnly:" + options.readOnly);
				 * $w.log("dComboDataList:" + options.dComboDataList);
				 * $w.log("dComboLabel:" + options.dComboLabel);
				 * $w.log("dComboValue:" + options.dComboValue);
				 *
				 * //event trigger
				 * udc_obj.trigger("onTelChange", [param1]); 
				*/
				var readOnly = options.readOnly;
				var ref = options.ref;
				var dcomboDataList = options.dComboDataList;	//selectbox nodeSet
				var dcomboLabel = options.dComboLabel;			//selectbox nodeSet Label
				var dcomboValue = options.dComboValue;			//selectbox nodeSet value;

				if(readOnly) {
					telNo1.setReadOnly(true);	//내부에 정의한 telNo1 selectbox를 readOnly
					telNo2.setReadOnly(true);	//내부에 정의한 telNo2 inputbox를 readOnly
					telNo3.setReadOnly(true);	//내부에 정의한 telNo3 inputbox를 readOnly
				}

				udc_obj.fireTelChange = true;
				udc_obj.setValue = function(telno) {
					var oldValue = udc_obj.getValue();
					var tel1 = telno.substr(0,3);
					var offsetTel3 = telno.length-4;
					var tel3 = telno.substr(offsetTel3);
					var tel2 = telno.substr(3).replace(tel3,"");
					udc_obj.fireTelChange = false;
					telNo1.setValue(tel1);
					telNo2.setValue(tel2);
					telNo3.setValue(tel3);

					if(oldValue != telno) {
	    				udc_obj.trigger("onTelChange", udc_obj.getValue());
					}					
					udc_obj.fireTelChange = true;
				};			

				udc_obj.getValue = function() {
					return telNo1.getValue() + telNo2.getValue() + telNo3.getValue();
				};

				udc_obj.setRef = function(ref) {
					if(typeof ref == "string" && ref.length > 0) {
						if( ! udc_obj.modelControl.isBinded() ) {  
							udc_obj.modelControl.useRef = true;
						}
						udc_obj.options.ref = ref;	
						udc_obj.modelControl.setRef( ref );
						udc_obj.refresh();
					}
				};

				udc_obj.refresh = function() {
					if(udc_obj.modelControl.isBinded()){
						var value = this.modelControl.getData();
						udc_obj.setValue(value);
					}
				};

				scwin.doInit = function() {
                    var frameId = $p.getFrameId() || $p.getParameter("w2xPath");
                    console.log("[udc_telNo] oncreated - " + frameId);
					telNo1.setNodeSet(dcomboDataList, dcomboLabel, dcomboValue);
					udc_obj.setRef(ref);
				};

				scwin.doInit();
